from __future__ import annotations

from dataclasses import dataclass

from pra_hf.skill_records import SkillRecord


@dataclass(frozen=True)
class SkillQuery:
    """One held-out request with deterministic skill-following checks."""

    query_id: str
    split: str
    query: str
    target_skill: str
    family: str
    hardness_level: str = "H0"
    query_style: str = "paraphrastic"
    language: str = "en"


@dataclass(frozen=True)
class _SkillSpec:
    name: str
    family: str
    description: str
    when_to_use: str
    validation_query: str
    test_query: str
    steps: tuple[str, str, str]
    constraint: str
    aliases: tuple[str, ...] = ()


